            toStringOutput.Add($"Ugma = {this.Ugma ?? "null"}");
            toStringOutput.Add($"Utma = {this.Utma ?? "null"}");
            toStringOutput.Add($"VariableAnnuity = {this.VariableAnnuity ?? "null"}");

            additionalProperties?
                .Select(kvp => $"[{kvp.Key}] = {kvp.Value.ToString(Formatting.None)}")
                .ToList()
                .ForEach(toStringOutput.Add);
        }
    }
}